export const c11Phy10HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(0, 229, 255, 0.05); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #00E5FF; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #00E5FF; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit X: Oscillations and Waves</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>1. Simple Harmonic Motion (S.H.M):</b>\n        <span style=\"color: #FFFFFF;\">To-and-fro oscillatory motion in which restoring force is directly proportional to displacement and acts towards mean position: F = -k x.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>2. Time Period & Frequency:</b>\n        <span style=\"color: #FFFFFF;\">Time Period T is time taken for one full oscillation. Frequency ν = 1/T is number of oscillations per second (Hz).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>3. Phase (Φ):</b>\n        <span style=\"color: #FFFFFF;\">The physical state of an oscillating particle regarding its instantaneous position and direction of motion: Φ = ω t + φ₀.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>4. Simple Pendulum Period:</b>\n        <span style=\"color: #FFFFFF;\">Time period of small-angle pendulum oscillations: T = 2π √(L/g). Independent of bob mass m.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>5. Total Energy in S.H.M:</b>\n        <span style=\"color: #FFFFFF;\">Sum of Kinetic and Potential energies: E = E_k + U = 1/2 m ω<sup>2</sup> A<sup>2</sup> = 1/2 k A<sup>2</sup> = Constant.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>6. Transverse vs Longitudinal Waves:</b>\n        <span style=\"color: #FFFFFF;\">Transverse: Particle vibration ⊥ wave direction (crests/troughs). Longitudinal: Vibration ∥ direction (compressions/rarefactions).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>7. Progressive Wave Equation:</b>\n        <span style=\"color: #FFFFFF;\">y(x,t) = A sin(k x - ω t + φ₀), where k = 2π/λ is wavenumber and wave speed v = ν λ = ω / k.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>8. Superposition Principle:</b>\n        <span style=\"color: #FFFFFF;\">Resultant displacement of two overlapping waves is vector sum of individual displacements: y(x,t) = y₁(x,t) + y₂(x,t).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>9. Standing Waves & Nodes:</b>\n        <span style=\"color: #FFFFFF;\">Interference of two identical counter-propagating waves. Nodes are zero amplitude points; Antinodes are maximum amplitude points.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>10. Beats Phenomenon:</b>\n        <span style=\"color: #FFFFFF;\">Periodic waxing and waning of sound intensity produced by superposition of two waves of close frequencies: f_b = |f₁ - f₂|.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- PART A: OSCILLATIONS -->\n  <h1 style=\"color: #00E5FF; border-bottom: 2.5px solid #00E5FF; padding-bottom: 6px; margin-top: 25px;\">PART A: OSCILLATIONS</h1>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 20px;\">1. Periodic Motion, Time Period, Frequency and Periodic Functions</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Periodic Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Motion that repeats itself at regular intervals of time T. Oscillatory motion is a bounded periodic motion about a mean equilibrium position.</p>\n  </div>\n  <p>A periodic function satisfies f(t + T) = f(t). The simplest harmonic periodic functions are sine and cosine functions: y(t) = A sin(ω t + φ₀).</p>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">2. Simple Harmonic Motion (S.H.M), Equations of Motion and Phase</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Simple Harmonic Motion (S.H.M)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A special type of periodic oscillatory motion in which restoring force F is proportional to displacement x and acts towards mean position: F = -k x.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>x(t) = A cos(ω t + φ) &nbsp;|&nbsp; v(t) = ± ω √(A<sup>2</sup> - x<sup>2</sup>) &nbsp;|&nbsp; a(t) = - ω<sup>2</sup> x &nbsp;|&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">d<sup>2</sup>x</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt<sup>2</sup></span>\n  </span> + ω<sup>2</sup> x = 0</b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Simple Harmonic Motion (S.H.M) Reference Circle & Phase Diagram\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"refGrad1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"40%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Side: Reference Circle (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Reference Circle &amp; S.H.M Projection</text>\n\n    <!-- Reference Circle -->\n    <circle cx=\"180\" cy=\"210\" r=\"110\" fill=\"rgba(0,229,255,0.08)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <line x1=\"70\" y1=\"210\" x2=\"290\" y2=\"210\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"180\" y1=\"100\" x2=\"180\" y2=\"320\" stroke=\"#475569\" stroke-width=\"2\"/>\n\n    <!-- Rotating Vector OP -->\n    <line x1=\"180\" y1=\"210\" x2=\"255\" y2=\"135\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n    <circle cx=\"255\" cy=\"135\" r=\"9\" fill=\"url(#refGrad1)\"/>\n    <text x=\"268\" y=\"130\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">P (t)</text>\n\n    <!-- Projection P' on X axis -->\n    <line x1=\"255\" y1=\"135\" x2=\"255\" y2=\"210\" stroke=\"#FFD700\" stroke-dasharray=\"3,3\" stroke-width=\"2\"/>\n    <circle cx=\"255\" cy=\"210\" r=\"7\" fill=\"#FFD700\"/>\n    <text x=\"250\" y=\"235\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">x(t) = A cos(ωt + φ)</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Phase Angle Φ = ω t + φ₀</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: S.H.M Equations Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. S.H.M Equations of Motion</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Displacement &amp; Velocity:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">x(t) = A cos(ω t + φ)</text>\n    <text x=\"182\" y=\"145\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"15.5\">v(t) = ± ω √(A² - x²)</text>\n\n    <rect x=\"10\" y=\"175\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"200\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Acceleration &amp; Differential Eq:</text>\n    <text x=\"182\" y=\"235\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">a(t) = - ω² x &nbsp;|&nbsp; d²x/dt² + ω² x = 0</text>\n\n    <rect x=\"10\" y=\"300\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"325\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Time Period &amp; Frequency:</text>\n    <text x=\"182\" y=\"358\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">T = 2π / ω = 1 / ν &nbsp;|&nbsp; ω = 2π ν</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Uniform circular motion projection on X axis generating S.H.M displacement x(t) = A cos(ωt+φ) and phase angle Φ.\n    </div>\n  </div>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">3. Oscillations of a Loaded Spring and Simple Pendulum</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Loaded Spring & Simple Pendulum):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Spring Period T = 2π √(m/k). Simple Pendulum Period T = 2π √(L/g), independent of bob mass m.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Spring T = 2π √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">k</span>\n  </span>) &nbsp;|&nbsp; Pendulum T = 2π √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span>) &nbsp;|&nbsp; Series k<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k<sub>1</sub> k<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">k<sub>1</sub> + k<sub>2</sub></span>\n  </span> &nbsp;|&nbsp; Parallel k<sub>eq</sub> = k<sub>1</sub> + k<sub>2</sub></b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Loaded Spring Mass System & Series/Parallel Springs\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"blockGrad2\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: Horizontal Loaded Spring (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Horizontal Spring-Mass Oscillator</text>\n\n    <!-- Rigid Wall -->\n    <rect x=\"40\" y=\"100\" width=\"15\" height=\"160\" fill=\"#475569\"/>\n\n    <!-- Helical Spring -->\n    <path d=\"M 55 180 Q 75 160 95 180 T 135 180 T 175 180 T 215 180\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n\n    <!-- Mass Block m -->\n    <rect x=\"215\" y=\"140\" width=\"80\" height=\"80\" rx=\"8\" fill=\"url(#blockGrad2)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"255\" y=\"185\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Mass m</text>\n\n    <line x1=\"255\" y1=\"230\" x2=\"255\" y2=\"280\" stroke=\"#76FF03\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <text x=\"255\" y=\"300\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Displacement x →</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Restoring Force F = - k x</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Spring Combinations & Period Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Loaded Spring Period &amp; Combinations</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Spring Time Period T:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">T = 2π √(m / k)</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Springs in Series:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">1 / k_eq = 1/k₁ + 1/k₂</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Equivalent stiffness decreases in series!</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Springs in Parallel:</text>\n    <text x=\"182\" y=\"348\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">k_eq = k₁ + k₂</text>\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">• Cutting spring in half doubles force constant k!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Horizontal spring mass m oscillator, Hooke's restoring force F = -kx, and series vs parallel stiffness rules.\n    </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Simple Pendulum Oscillation Geometry & Restoring Force\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"bobGrad3\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFFDE7\"/>\n      <stop offset=\"40%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"100%\" stop-color=\"#D4AC0D\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Side: Simple Pendulum Geometry (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Simple Pendulum Force Vector Diagram</text>\n\n    <!-- Rigid Ceiling -->\n    <rect x=\"110\" y=\"60\" width=\"140\" height=\"12\" fill=\"#475569\"/>\n\n    <!-- Vertical Mean Line -->\n    <line x1=\"180\" y1=\"72\" x2=\"180\" y2=\"330\" stroke=\"#475569\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n\n    <!-- String Length L at angle θ -->\n    <line x1=\"180\" y1=\"72\" x2=\"260\" y2=\"260\" stroke=\"#00E5FF\" stroke-width=\"3\"/>\n    <text x=\"230\" y=\"160\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Length L</text>\n\n    <!-- Pendulum Bob mass m -->\n    <circle cx=\"260\" cy=\"260\" r=\"18\" fill=\"url(#bobGrad3)\"/>\n\n    <!-- Forces: Weight mg, Tension T, Restoring mg sinθ -->\n    <line x1=\"260\" y1=\"260\" x2=\"260\" y2=\"340\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n    <text x=\"270\" y=\"330\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">mg</text>\n\n    <line x1=\"260\" y1=\"260\" x2=\"200\" y2=\"280\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <text x=\"130\" y=\"300\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">mg sinθ (Restoring)</text>\n\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Small Angle Approximation: sinθ ≈ θ = x/L</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Pendulum Time Period Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Simple Pendulum Time Period</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Pendulum Period Formula (T):</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">T = 2π √(L / g)</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Seconds Pendulum (T = 2 Seconds):</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">Length L ≈ 0.993 m ≈ 1 Meter</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Independent of bob mass m and amplitude θ!</text>\n\n    <rect x=\"10\" y=\"295\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"320\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Factors Affecting Pendulum Period:</text>\n    <text x=\"25\" y=\"348\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• In accelerating elevator: T = 2π √(L / (g ± a))</text>\n    <text x=\"25\" y=\"370\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Inside orbiting satellite (g_eff = 0): T = ∞</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Pendulum bob force resolution (mg sinθ restoring component) deriving small-angle time period T = 2π √(L/g).\n    </div>\n  </div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">4. Energy in S.H.M. Kinetic and Potential Energies</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Energy Conservation in S.H.M):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Kinetic E_k = 1/2 k (A<sup>2</sup> - x<sup>2</sup>) and Potential U = 1/2 k x<sup>2</sup> sum to a constant total energy E = 1/2 k A<sup>2</sup>.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E<sub>k</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m ω<sup>2</sup> (A<sup>2</sup> - x<sup>2</sup>) &nbsp;|&nbsp; U = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m ω<sup>2</sup> x<sup>2</sup> &nbsp;|&nbsp; E<sub>total</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m ω<sup>2</sup> A<sup>2</sup> = Const</b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Energy Breakdown in S.H.M (E_k, U, E_total Graphs)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: Energy Graphs (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Energy vs Displacement Graph in S.H.M</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"330\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"190\" y1=\"330\" x2=\"190\" y2=\"70\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"335\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Displacement x</text>\n\n    <!-- Total Energy E Line (Constant) -->\n    <line x1=\"70\" y1=\"110\" x2=\"310\" y2=\"110\" stroke=\"#FFD700\" stroke-width=\"3\"/>\n    <text x=\"190\" y=\"95\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Total E = ½ k A²</text>\n\n    <!-- Potential Energy Parabola U(x) = 1/2 k x² -->\n    <path d=\"M 70 110 Q 190 330 310 110\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3.5\"/>\n    <text x=\"260\" y=\"190\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">U = ½ k x²</text>\n\n    <!-- Kinetic Energy Parabola Ek(x) = 1/2 k (A² - x²) -->\n    <path d=\"M 70 330 Q 190 110 310 330\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n    <text x=\"190\" y=\"150\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">E_k = ½ k (A² - x²)</text>\n\n    <text x=\"70\" y=\"350\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">-A</text>\n    <text x=\"190\" y=\"350\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">0</text>\n    <text x=\"310\" y=\"350\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">+A</text>\n\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">At x = ± A / √2 :  E_k = U = ½ E_total</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Energy Formulae Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. S.H.M Energy Conversions</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Kinetic Energy (E_k):</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">E_k = ½ m ω² (A² - x²)</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Potential Energy (U):</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">U = ½ m ω² x² = ½ k x²</text>\n\n    <rect x=\"10\" y=\"270\" width=\"345\" height=\"140\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"295\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Total Mechanical Energy (E):</text>\n    <text x=\"182\" y=\"330\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">E = E_k + U = ½ m ω² A²</text>\n    <text x=\"182\" y=\"365\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Average E_k = Average U = ¼ m ω² A²</text>\n    <text x=\"182\" y=\"390\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"12.5\">• Total energy E is strictly conserved and independent of x!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Parabolic energy curves E_k(x) and U(x) intersecting at x = ± A / √2 with constant total energy line E = 1/2 k A².\n    </div>\n  </div>\n\n  <!-- PART B: WAVES -->\n  <h1 style=\"color: #00E5FF; border-bottom: 2.5px solid #00E5FF; padding-bottom: 6px; margin-top: 35px;\">PART B: WAVES</h1>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 20px;\">5. Wave Motion, Transverse and Longitudinal Waves & Speed of Travelling Wave</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Transverse & Longitudinal Waves):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Transverse: Medium particle vibration ⊥ wave propagation. Longitudinal: Particle vibration ∥ wave propagation.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>String Speed: v = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">μ</span>\n  </span>) &nbsp;|&nbsp; Laplace Sound Speed: v = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">γ P</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">ρ</span>\n  </span>)</b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Transverse vs Longitudinal Progressive Waves\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"waveGrad5\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"50%\" stop-color=\"#76FF03\"/>\n      <stop offset=\"100%\" stop-color=\"#00E5FF\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: Transverse & Longitudinal Wave Profiles (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Transverse vs Longitudinal Wave Types</text>\n\n    <!-- Transverse Wave Profile -->\n    <path d=\"M 40 120 Q 100 40 160 120 T 280 120 T 330 120\" fill=\"none\" stroke=\"url(#waveGrad5)\" stroke-width=\"3.5\"/>\n    <text x=\"100\" y=\"55\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Crest</text>\n    <text x=\"220\" y=\"170\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Trough</text>\n    <text x=\"182\" y=\"195\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\">Transverse: Vibration ⊥ Propagation</text>\n\n    <!-- Longitudinal Wave Profile (Compressions & Rarefactions) -->\n    <rect x=\"40\" y=\"240\" width=\"40\" height=\"40\" fill=\"rgba(0,229,255,0.4)\"/>\n    <rect x=\"80\" y=\"240\" width=\"80\" height=\"40\" fill=\"rgba(0,229,255,0.1)\"/>\n    <rect x=\"160\" y=\"240\" width=\"40\" height=\"40\" fill=\"rgba(0,229,255,0.4)\"/>\n    <rect x=\"200\" y=\"240\" width=\"80\" height=\"40\" fill=\"rgba(0,229,255,0.1)\"/>\n\n    <text x=\"60\" y=\"300\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Comp C</text>\n    <text x=\"120\" y=\"300\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Rare R</text>\n    <text x=\"182\" y=\"335\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\">Longitudinal: Vibration ∥ Propagation</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Progressive Wave Formulae Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Progressive Wave Displacement</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Travelling Wave Equation:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">y(x,t) = A sin(k x - ω t + φ)</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Wavenumber k &amp; Wave Speed v:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">k = 2π / λ &nbsp;|&nbsp; v = ν λ = ω / k</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Speeds in Mediums:</text>\n    <text x=\"25\" y=\"343\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Stretched String: v = √(T / μ)</text>\n    <text x=\"25\" y=\"365\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Laplace Gas Speed: v = √(γ P / ρ)</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Crests and Troughs of Transverse wave vs Compressions and Rarefactions of Longitudinal wave.\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">6. Displacement Relation for a Progressive Wave & Principle of Superposition</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Progressive Wave Equation):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Displacement relation y(x,t) = A sin(k x - ω t + φ₀) representing a wave travelling in +x direction.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>y(x,t) = A sin(k x - ω t + φ<sub>0</sub>) &nbsp;|&nbsp; k = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2π</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">λ</span>\n  </span> &nbsp;|&nbsp; v = ν λ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ω</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">k</span>\n  </span></b></div>\n\n  <!-- SECTION 7 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">7. Reflection of Waves, Standing Waves in Strings and Organ Pipes</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Standing Waves & Organ Pipes):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Open Pipe: f_n = n (v / 2L) (all harmonics). Closed Pipe: f_n = (2n - 1) (v / 4L) (odd harmonics only).</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Open Pipe: f<sub>n</sub> = n ( <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2L</span>\n  </span> ) &nbsp;|&nbsp; Closed Pipe: f<sub>n</sub> = (2n - 1) ( <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4L</span>\n  </span> )</b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Reflection of Waves at Rigid vs Free Boundary\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: Reflection Diagrams (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Reflection at Rigid vs Free Boundary</text>\n\n    <!-- Rigid Fixed Boundary (Phase Change π) -->\n    <rect x=\"310\" y=\"60\" width=\"15\" height=\"140\" fill=\"#475569\"/>\n    <path d=\"M 50 110 Q 110 50 170 110\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <text x=\"110\" y=\"130\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Incident Crest →</text>\n    <path d=\"M 180 150 Q 240 210 300 150\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n    <text x=\"220\" y=\"130\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">← Reflected Trough</text>\n    <text x=\"182\" y=\"215\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Rigid End: 180° (π) Phase Flip!</text>\n\n    <!-- Free Ring Boundary (No Phase Change) -->\n    <line x1=\"315\" y1=\"240\" x2=\"315\" y2=\"360\" stroke=\"#94A3B8\" stroke-width=\"4\"/>\n    <circle cx=\"315\" cy=\"300\" r=\"8\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3\"/>\n    <path d=\"M 50 300 Q 110 240 170 300\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <path d=\"M 180 300 Q 240 240 300 300\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3\"/>\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Free End: Zero Phase Change (0°)</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Wave Reflection Summary Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Superposition &amp; Boundary Laws</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Reflected Wave at Rigid End:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">y_r = - A sin(k x + ω t)</text>\n\n    <rect x=\"10\" y=\"175\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"200\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Reflected Wave at Free End:</text>\n    <text x=\"182\" y=\"235\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">y_r = + A sin(k x + ω t)</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Principle of Superposition:</text>\n    <text x=\"182\" y=\"348\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">y_net(x,t) = y₁(x,t) + y₂(x,t)</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Incident wave pulse reflecting with 180° (π) phase flip at rigid boundary vs 0° phase shift at free boundary.\n    </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Standing Waves in Strings and Organ Pipes (Nodes & Antinodes)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: Standing Wave Loops (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Standing Wave Harmonics (Nodes &amp; Antinodes)</text>\n\n    <!-- Fundamental Mode (1 Loop) -->\n    <line x1=\"40\" y1=\"100\" x2=\"320\" y2=\"100\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <path d=\"M 40 100 Q 180 50 320 100 Q 180 150 40 100\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <circle cx=\"40\" cy=\"100\" r=\"5\" fill=\"#FF512F\"/>\n    <circle cx=\"320\" cy=\"100\" r=\"5\" fill=\"#FF512F\"/>\n    <text x=\"40\" y=\"125\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"12\">Node N</text>\n    <text x=\"180\" y=\"80\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Antinode A</text>\n    <text x=\"320\" y=\"125\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"12\">Node N</text>\n\n    <!-- 2nd Harmonic (2 Loops) -->\n    <path d=\"M 40 250 Q 110 200 180 250 Q 250 200 320 250\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n    <path d=\"M 40 250 Q 110 300 180 250 Q 250 300 320 250\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Distance Node to Node = λ / 2  |  Node to Antinode = λ / 4</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Organ Pipes Harmonics Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Organ Pipes Frequency Laws</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Open Organ Pipe (Both Ends Open):</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">f_n = n (v / 2L) &nbsp; (n = 1, 2, 3...)</text>\n    <text x=\"182\" y=\"148\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">✓ ALL harmonics (even &amp; odd) are present!</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Closed Organ Pipe (One End Closed):</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">f_n = (2n - 1) (v / 4L) &nbsp; (n = 1, 2...)</text>\n    <text x=\"182\" y=\"278\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\">✓ ONLY ODD harmonics (1, 3, 5...) are present!</text>\n\n    <rect x=\"10\" y=\"315\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"340\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Standing Wave Equation:</text>\n    <text x=\"182\" y=\"372\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">y(x,t) = 2 A sin(k x) cos(ω t)</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Standing wave harmonic loops showing Nodes N and Antinodes A in stretched strings and organ pipes.\n    </div>\n  </div>\n\n  <!-- SECTION 8 -->\n  <h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">8. Beats and Harmonics</h2>\n  \n  <div style=\"background: rgba(0, 229, 255, 0.06); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Beats Phenomenon):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Periodic variation in intensity of sound produced when two sound waves of slightly different frequencies superpose: f_b = |f₁ - f₂|.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Beat Frequency: f<sub>b</sub> = | f<sub>1</sub> - f<sub>2</sub> | &nbsp;|&nbsp; Beat Period: T<sub>b</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">| f<sub>1</sub> - f<sub>2</sub> |</span>\n  </span> &nbsp; (f<sub>b</sub> ≤ 10 Hz for human ear)</b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00E5FF; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(0, 229, 255, 0.25);\">\n    <div style=\"color: #00E5FF; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Beats Phenomenon & Envelope Waveform (f_b = |f₁ - f₂|)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"beatGrad8\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"50%\" stop-color=\"#FF512F\"/>\n      <stop offset=\"100%\" stop-color=\"#76FF03\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: Beats Modulation Envelope (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Beats Modulated Waveform &amp; Envelope</text>\n\n    <!-- Center Line -->\n    <line x1=\"40\" y1=\"200\" x2=\"330\" y2=\"200\" stroke=\"#475569\" stroke-width=\"2\"/>\n\n    <!-- Beat Envelope Top & Bottom -->\n    <path d=\"M 40 200 Q 115 100 190 200 Q 265 100 330 200\" fill=\"none\" stroke=\"#FFD700\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n    <path d=\"M 40 200 Q 115 300 190 200 Q 265 300 330 200\" fill=\"none\" stroke=\"#FFD700\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n\n    <!-- High Frequency Wave Inside Envelope -->\n    <path d=\"M 40 200 Q 60 160 80 200 Q 100 240 120 200 Q 140 160 160 200 Q 180 240 190 200 Q 210 160 230 200 Q 250 240 270 200 Q 290 160 310 200 Q 320 220 330 200\" fill=\"none\" stroke=\"url(#beatGrad8)\" stroke-width=\"3\"/>\n\n    <circle cx=\"115\" cy=\"150\" r=\"6\" fill=\"#76FF03\"/>\n    <text x=\"115\" y=\"130\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Waxing (Max Sound)</text>\n\n    <circle cx=\"190\" cy=\"200\" r=\"6\" fill=\"#FF512F\"/>\n    <text x=\"190\" y=\"225\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Waning (Min Sound)</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Beat Period T_b = 1 / f_b = 1 / |f₁ - f₂|</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Beats Equations Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Beats Frequency &amp; Applications</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Beat Frequency Formula (f_b):</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">f_b = | f₁ - f₂ |</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Persistence of Hearing Limit:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">f_b ≤ 10 Beats / Second</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Human ear can distinguish beats if f_b ≤ 10 Hz!</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Applications of Beats:</text>\n    <text x=\"25\" y=\"343\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Tuning musical instruments (piano, violin, sitar)</text>\n    <text x=\"25\" y=\"365\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Determining unknown frequency of a tuning fork</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Waxing and waning modulated sound envelope waveform with beat frequency f_b = |f1 - f2|.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(0, 229, 255, 0.05); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #00E5FF; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #00E5FF; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Formulae, Oscillations, Organ Pipes & Wave Motion Summary for Unit X</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• S.H.M Displacement &amp; Speed:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">x(t) = A cos(ω t + φ)<br>v = ± ω √(A<sup>2</sup> - x<sup>2</sup>) &nbsp;|&nbsp; a = - ω<sup>2</sup> x</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• Oscillator Time Periods:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Spring T = 2π √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">k</span>\n  </span>)<br>Pendulum T = 2π √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span>)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• Total S.H.M Energy:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">E<sub>k</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m ω<sup>2</sup> (A<sup>2</sup> - x<sup>2</sup>)<br>U = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m ω<sup>2</sup> x<sup>2</sup> &nbsp;|&nbsp; E = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> k A<sup>2</sup></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• Progressive Wave Equation:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">y(x,t) = A sin(k x - ω t + φ<sub>0</sub>)<br>k = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2π</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">λ</span>\n  </span> &nbsp;|&nbsp; v = ν λ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">ω</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">k</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• Organ Pipe Frequencies:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Open: f<sub>n</sub> = n (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2L</span>\n  </span>) (All harmonics)<br>Closed: f<sub>n</sub> = (2n-1) (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4L</span>\n  </span>) (Odd harmonics)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style='color: #00E5FF; display: block; margin-bottom: 3px;'>• Beats &amp; Wave Speed:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">f<sub>b</sub> = |f<sub>1</sub> - f<sub>2</sub>|<br>String v = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">μ</span>\n  </span>) &nbsp;|&nbsp; Sound v = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">γ P</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">ρ</span>\n  </span>)</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy10HtmlSolutions = "<style>\n    p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) { text-align: justify !important; }\n    h1, h2, h3, h4, h5, h6 { text-align: left; }\n    .text-center { text-align: center !important; }\n  </style>\n  <div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  <h1 style=\"color: #00E5FF; border-bottom: 2.5px solid #00E5FF; padding-bottom: 6px; margin-top: 10px;\">NCERT & Textbook Standard Exercise Solutions — Unit X: Oscillations and Waves</h1><h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 25px;\">SECTION 1: MULTIPLE CHOICE QUESTIONS (MCQs 1 - 25)</h2>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q1: In Simple Harmonic Motion (S.H.M), restoring force F is proportional to:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Displacement x</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Square of displacement x²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Velocity v</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Time period T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> By definition of S.H.M, F = -k x, so restoring force is proportional to displacement x.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q2: The acceleration of a particle executing S.H.M at displacement x is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) +ω x</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) -ω² x</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) -ω x²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) +ω² x²</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Differential equation of S.H.M gives a = -ω² x.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q3: The maximum velocity of a particle executing S.H.M of amplitude A and angular frequency ω is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) ω A²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) ω A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) ω² A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) ω / A</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> v = ω √(A² - x²). Maximum velocity occurs at mean position (x=0), so v_max = ω A.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q4: At what displacement x from mean position is kinetic energy equal to potential energy in S.H.M?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) x = ± A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) x = ± A / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) x = ± A / √2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) x = 0</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> ½ k (A² - x²) = ½ k x² ⇒ A² - x² = x² ⇒ 2 x² = A² ⇒ x = ± A / √2.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q5: The total mechanical energy of a simple harmonic oscillator of amplitude A is proportional to:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) A²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1/A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) √A</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Total energy E = ½ m ω² A² ∝ A².</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q6: The time period of a simple pendulum of length L is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) T = 2π √(g / L)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) T = 2π √(L / g)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) T = ½π √(L / g)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) T = 2π L / g</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> T = 2π √(L / g).</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q7: If the length of a simple pendulum is increased by 44%, its time period increases by:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 20%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 44%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 22%</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 10%</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> T ∝ √L. T'/T = √(1.44) = 1.20, representing a 20% increase.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q8: A seconds pendulum has a time period of:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1 second</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 2 seconds</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 0.5 second</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 4 seconds</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> A seconds pendulum takes 1 second to swing from one extreme to another, so its full period T = 2 s.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q9: When a spring of force constant k is cut into two equal halves, force constant of each half becomes:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) k / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) k</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 2 k</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 4 k</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Force constant k ∝ 1/L. Halving the length doubles the stiffness to 2k.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q10: Two springs of force constants k₁ and k₂ are connected in parallel. Equivalent force constant is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) k₁ + k₂</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) k₁ k₂ / (k₁ + k₂)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) k₁ - k₂</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) √(k₁ k₂)</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> For parallel springs, equivalent spring constant k_eq = k₁ + k₂.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q11: In a progressive wave y(x,t) = A sin(k x - ω t), wave speed v is equal to:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) ω k</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) ω / k</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) k / ω</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1 / (ω k)</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Wave velocity v = ν λ = (ω / 2π) (2π / k) = ω / k.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q12: Phase difference Δφ between two points separated by path difference Δx is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Δφ = (2π / λ) Δx</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Δφ = (λ / 2π) Δx</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Δφ = 2π λ Δx</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Δφ = π Δx</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Phase difference Δφ = k Δx = (2π / λ) Δx.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q13: Speed of sound in a gas according to Laplace correction is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) v = √(P / ρ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) v = √(γ P / ρ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) v = √(ρ / P)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) v = γ P / ρ</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Laplace corrected sound speed for adiabatic compression is v = √(γ P / ρ).</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q14: When a wave reflects from a rigid boundary, phase change introduced is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 0</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) π / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) π (180°)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 2π</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Reflection at a fixed/rigid boundary introduces a phase inversion of π radians (180°).</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q15: In a standing wave, the distance between two consecutive nodes is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) λ</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) λ / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) λ / 4</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 2λ</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Distance between node to consecutive node (or antinode to antinode) = λ / 2.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q16: An open organ pipe of length L produces fundamental frequency f. If one end is closed, fundamental frequency becomes:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) f / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 2 f</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) f</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 4 f</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Open pipe f_open = v / (2L). Closed pipe f_closed = v / (4L) = f_open / 2.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q17: A closed organ pipe produces harmonics of frequencies:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) All harmonics (f, 2f, 3f...)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Only odd harmonics (f, 3f, 5f...)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Only even harmonics (2f, 4f...)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) No harmonics</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Closed organ pipes contain only odd harmonics f_n = (2n-1) v / (4L).</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q18: Beat frequency produced by two sound sources of frequencies f₁ and f₂ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) f₁ + f₂</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) | f₁ - f₂ |</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) (f₁ + f₂) / 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) f₁ f₂</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Beat frequency f_b = | f₁ - f₂ |.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q19: Maximum number of beats per second that human ear can resolve is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 5</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 10</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 20</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 50</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Due to persistence of hearing (0.1 s), human ear resolves beats if f_b ≤ 10 Hz.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q20: Speed of transverse wave in a stretched string of tension T and mass per unit length μ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) v = √(T / μ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) v = √(μ / T)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) v = T / μ</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) v = T μ</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Transverse wave speed in stretched string v = √(T / μ).</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q21: In S.H.M, the ratio of velocity at mean position to acceleration at extreme position is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1 / ω</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) ω</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) ω²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> v_mean = ω A, a_extreme = ω² A. Ratio v_mean / a_extreme = (ω A) / (ω² A) = 1 / ω.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q22: A particle executes S.H.M with time period T. Time taken to travel from mean position to half amplitude (x = A/2) is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) T / 6</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) T / 12</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) T / 4</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) T / 8</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> x = A sin(ω t) ⇒ A/2 = A sin(ω t) ⇒ sin(ω t) = 1/2 ⇒ ω t = π/6 ⇒ (2π/T) t = π/6 ⇒ t = T / 12.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q23: The displacement of a progressive wave is given by y = 5 sin(100π t - 0.4π x) cm. Wavelength λ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 5 cm</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 0.4 cm</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 5 cm</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 5 cm</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> k = 0.4π = 2π / λ ⇒ λ = 2 / 0.4 = 5 cm.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q24: If two tuning forks of frequencies 256 Hz and 260 Hz are sounded together, beat period is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 4 s</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 0.25 s</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 0.5 s</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 2 s</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> f_b = 260 - 256 = 4 Hz. Beat period T_b = 1 / f_b = 1 / 4 = 0.25 seconds.</div>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q25: Frequency of fundamental mode of stretched string of length L, tension T, and mass density μ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) f = (1 / 2L) √(T / μ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) f = (1 / L) √(T / μ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) f = 2L √(T / μ)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) f = (1 / 4L) √(T / μ)</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #00E5FF; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Fundamental frequency f₁ = v / 2L = (1 / 2L) √(T / μ).</div>\n    </div><h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">SECTION 2: VERY SHORT ANSWER QUESTIONS (VSAs 26 - 55)</h2>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q26: Define Simple Harmonic Motion (S.H.M).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> To-and-fro oscillatory motion in which restoring force F is directly proportional to displacement x and acts towards mean position (F = -k x).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q27: Write the differential equation of S.H.M.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> d²x/dt² + ω² x = 0.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q28: Write the expression for displacement in S.H.M.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> x(t) = A cos(ω t + φ₀) or x(t) = A sin(ω t + φ₀).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q29: What is the phase angle of an oscillating particle?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The quantity (ω t + φ₀) which describes the state of position and motion of the particle at any instant.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q30: Define Epoch or initial phase.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The phase angle φ₀ of the oscillating particle at initial time t = 0.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q31: Write the formula for velocity of a particle in S.H.M at displacement x.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v = ± ω √(A² - x²).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q32: Write the formula for acceleration of a particle in S.H.M at displacement x.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> a = - ω² x.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q33: At what position is velocity maximum in S.H.M?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> At mean position (x = 0), where v_max = ω A.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q34: At what position is acceleration maximum in S.H.M?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> At extreme positions (x = ± A), where |a_max| = ω² A.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q35: Write the formula for time period of a loaded spring.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> T = 2π √(m / k).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q36: Write the formula for time period of a simple pendulum.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> T = 2π √(L / g).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q37: What is a Seconds Pendulum?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A pendulum whose time period is exactly 2 seconds (length L ≈ 0.993 m ≈ 1 m).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q38: Write the expression for total mechanical energy in S.H.M.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> E = ½ m ω² A² = ½ k A².</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q39: What is the relation between frequency of S.H.M and frequency of its kinetic energy?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Kinetic energy oscillates at twice the frequency of S.H.M (ν_KE = 2 ν).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q40: Define Transverse Wave.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A wave in which medium particles vibrate perpendicular to the direction of wave propagation (forming crests and troughs).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q41: Define Longitudinal Wave.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A wave in which medium particles vibrate parallel to the direction of wave propagation (forming compressions and rarefactions).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q42: Write the formula for speed of transverse wave in a stretched string.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v = √(T / μ), where T is tension and μ is mass per unit length.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q43: Write Laplace's corrected formula for speed of sound in gas.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v = √(γ P / ρ).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q44: Write the general progressive wave equation moving in +x direction.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> y(x,t) = A sin(k x - ω t + φ₀).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q45: Write the relation between wavenumber k and wavelength λ.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> k = 2π / λ.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q46: State the Principle of Superposition of Waves.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Resultant displacement at any point is the vector sum of displacements produced by individual overlapping waves: y = y₁ + y₂.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q47: What is a Standing or Stationary Wave?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A wave pattern formed by the superposition of two identical waves travelling in opposite directions, characterized by fixed nodes and antinodes.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q48: Define Nodes and Antinodes in a standing wave.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Nodes: Points of zero displacement. Antinodes: Points of maximum displacement.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q49: What is the distance between a node and an adjacent antinode?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> λ / 4.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q50: Write the formula for fundamental frequency of an open organ pipe of length L.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> f₁ = v / 2L (all harmonics present).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q51: Write the formula for fundamental frequency of a closed organ pipe of length L.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> f₁ = v / 4L (only odd harmonics present).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q52: Define Beats.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Periodic waxing and waning of sound intensity produced when two sound waves of slightly different frequencies superpose.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q53: Write the formula for beat frequency f_b.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> f_b = | f₁ - f₂ |.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q54: Why do we hear no beats if frequency difference exceeds 10 Hz?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Due to persistence of hearing limit (~0.1 s), human ear cannot resolve sound pulses separated by less than 0.1 s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q55: Can transverse waves travel through gases? Why?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> No, because gases lack shear rigidity (shear modulus G = 0).</p>\n    </div><h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">SECTION 3: SHORT ANSWER QUESTIONS (SAs 56 - 85)</h2>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q56: Derive differential equation of S.H.M and write expressions for displacement, velocity, and acceleration.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Restoring force F = -k x ⇒ m d²x/dt² = -k x ⇒ d²x/dt² + (k/m) x = 0. Putting ω² = k/m gives d²x/dt² + ω² x = 0.\nSolution: x(t) = A cos(ω t + φ). Velocity v = dx/dt = -ω A sin(ω t + φ) = ±ω √(A² - x²). Acceleration a = dv/dt = -ω² A cos(ω t + φ) = -ω² x.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q57: Derive expression for time period of a simple pendulum T = 2π √(L/g).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Restoring torque τ = -m g L sinθ ≈ -m g L θ (for small θ). Rotational equation I d²θ/dt² = -m g L θ. With I = m L², d²θ/dt² + (g/L) θ = 0. Comparing with d²θ/dt² + ω² θ = 0 gives ω = √(g/L), so T = 2π/ω = 2π √(L/g).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q58: Derive expressions for Kinetic, Potential, and Total Energy in S.H.M. Show that total energy is conserved.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Kinetic Energy E_k = ½ m v² = ½ m ω² (A² - x²).\n2. Potential Energy U = ∫ k x dx = ½ k x² = ½ m ω² x².\n3. Total Energy E = E_k + U = ½ m ω² (A² - x²) + ½ m ω² x² = ½ m ω² A² = ½ k A² = Constant (Independent of x).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q59: Derive time period of a spring-mass system for: (i) Series combination, (ii) Parallel combination.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Series: Both springs experience same force F. Total extension x = x₁ + x₂ = F/k₁ + F/k₂ = F(1/k₁ + 1/k₂). k_eq = k₁ k₂ / (k₁ + k₂). T = 2π √(m / k_eq).\n2. Parallel: Both springs experience same extension x. Total force F = F₁ + F₂ = k₁ x + k₂ x = (k₁ + k₂) x. k_eq = k₁ + k₂. T = 2π √(m / (k₁ + k₂)).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q60: Differentiate between Transverse and Longitudinal waves with 3 examples of each.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Transverse: Particle vibration ⊥ wave direction; forms crests/troughs; propagates in solids/strings (e.g. string waves, light, seismic S-waves).\n2. Longitudinal: Particle vibration ∥ wave direction; forms compressions/rarefactions; propagates in solids, liquids, gases (e.g. sound waves, organ pipe waves, seismic P-waves).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q61: Explain Newton's formula for speed of sound in air and Laplace's correction.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Newton assumed isothermal compression (B = P): v = √(P / ρ) = √(1.013×10⁵ / 1.293) = 280 m/s (20% lower than actual 332 m/s).\n2. Laplace corrected that compressions are adiabatic (B = γ P): v = √(γ P / ρ) = √(1.4 × 101300 / 1.293) = 332 m/s (Matches experiment).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q62: Explain reflection of progressive wave at: (i) Rigid boundary, (ii) Free boundary with equations.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Rigid boundary: Particle displacement is zero. Reflected wave y_r = -A sin(k x + ω t) (180° or π phase shift).\n2. Free boundary: Particle displacement is maximum. Reflected wave y_r = +A sin(k x + ω t) (0° phase shift).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q63: Derive expression for standing wave formed by superposition of incident and reflected wave at rigid boundary.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> y₁ = A sin(k x - ω t), y₂ = -A sin(k x + ω t). Resultant y = y₁ + y₂ = A [sin(k x - ω t) - sin(k x + ω t)] = -2 A sin(k x) cos(ω t). Nodes occur at sin(k x) = 0 ⇒ k x = n π ⇒ x = n λ / 2.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q64: Show that an open organ pipe produces all harmonics while a closed organ pipe produces only odd harmonics.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Open Pipe (Both ends antinodes): L = n λ / 2 ⇒ λ = 2L / n ⇒ f_n = n (v / 2L) (n = 1, 2, 3... All harmonics).\n2. Closed Pipe (Node at closed end, Antinode at open end): L = (2n-1) λ / 4 ⇒ f_n = (2n-1) (v / 4L) (n = 1, 2... Only odd harmonics 1, 3, 5...).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q65: Explain the formation of Beats mathematically and derive formula for beat frequency f_b = |f₁ - f₂|.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> y₁ = A cos(2π f₁ t), y₂ = A cos(2π f₂ t). Resultant y = 2 A cos[π (f₁ - f₂) t] cos[π (f₁ + f₂) t]. Amplitude modulation frequency is ½ (f₁ - f₂). Sound intensity (proportional to A²) varies at frequency f_b = |f₁ - f₂|.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q66: A particle executes S.H.M of amplitude 5 cm and period 2 s. Find max velocity and max acceleration.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> ω = 2π / T = 2π / 2 = π rad/s.\n1. v_max = ω A = π × 5 = 15.71 cm/s = 0.157 m/s.\n2. a_max = ω² A = π² × 5 = 49.35 cm/s² = 0.494 m/s².</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q67: A 0.2 kg block on horizontal spring oscillates with amplitude 0.1 m and frequency 2 Hz. Find force constant k and max energy.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> ω = 2π ν = 2π × 2 = 4π rad/s.\n1. k = m ω² = 0.2 × (4π)² = 0.2 × 157.91 = 31.58 N/m.\n2. Total Energy E = ½ k A² = ½ × 31.58 × (0.1)² = 0.158 Joules.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q68: A simple pendulum has time period 2.0 s on Earth (g = 9.8 m/s²). Find its length and period on Moon (g_moon = 1.6 m/s²).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Earth: L = g T² / (4 π²) = 9.8 × 4 / 39.48 = 0.993 m ≈ 1 m.\n2. Moon: T_moon = 2π √(L / g_moon) = 2π √(0.993 / 1.6) = 2π √(0.6206) = 2π × 0.7878 = 4.95 seconds.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q69: A progressive wave equation is y = 0.05 sin(200 π t - 0.5 π x) where x, y in meters and t in seconds. Find: (i) Amplitude, (ii) Frequency, (iii) Wavelength, (iv) Wave velocity.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Amplitude A = 0.05 m.\n2. ω = 200π ⇒ 2π ν = 200π ⇒ ν = 100 Hz.\n3. k = 0.5π ⇒ 2π / λ = 0.5π ⇒ λ = 4 m.\n4. Velocity v = ν λ = 100 × 4 = 400 m/s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q70: A 1 m long steel wire of mass 10 g is stretched with tension 400 N. Find fundamental frequency of transverse vibration.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Linear density μ = m / L = 0.010 kg / 1.0 m = 0.010 kg/m.\nWave speed v = √(T / μ) = √(400 / 0.010) = √40000 = 200 m/s.\nFundamental frequency f₁ = v / 2L = 200 / (2 × 1.0) = 100 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q71: An open organ pipe 30 cm long produces sound in air (v = 330 m/s). Find fundamental frequency and 3rd harmonic.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> L = 0.30 m.\n1. Fundamental f₁ = v / 2L = 330 / (2 × 0.30) = 550 Hz.\n2. 3rd Harmonic f₃ = 3 f₁ = 3 × 550 = 1650 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q72: A closed organ pipe 20 cm long produces fundamental frequency. Find frequency of fundamental and next harmonic (v = 340 m/s).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> L = 0.20 m.\n1. Fundamental f₁ = v / 4L = 340 / (4 × 0.20) = 425 Hz.\n2. Next harmonic (3rd harmonic) f₃ = 3 f₁ = 3 × 425 = 1275 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q73: Two tuning forks A and B sounded together produce 5 beats/s. On loading fork A with wax, beat frequency decreases to 2 beats/s. If f_B = 256 Hz, find original f_A.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> f_A = f_B ± 5 = 256 ± 5 = 261 Hz or 251 Hz.\nLoading A with wax decreases f_A. If f_A = 261 Hz, dropping f_A reduces beat frequency |f_A - 256| from 5 to 2. Thus original f_A = 261 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q74: At what displacement is velocity of S.H.M particle equal to half its maximum velocity?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> v = v_max / 2 ⇒ ω √(A² - x²) = ω A / 2 ⇒ A² - x² = A² / 4 ⇒ x² = 3/4 A² ⇒ x = ± (√3 / 2) A ≈ ± 0.866 A.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q75: A body of mass 1 kg attached to spring executes S.H.M with period 1 s. What mass must be added to increase period to 2 s?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T ∝ √m. T₂ / T₁ = √(m₂ / m₁) ⇒ 2 / 1 = √(m₂ / 1) ⇒ m₂ = 4 kg. Mass to be added = 4 - 1 = 3 kg.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q76: A spring extends by 5 cm when loaded with 2 kg. Find force constant k and time period of oscillation when pulled and released.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. k = F / x = (2 kg × 9.8 N/kg) / 0.05 m = 19.6 / 0.05 = 392 N/m.\n2. T = 2π √(m / k) = 2π √(2 / 392) = 2π √(1 / 196) = 2π / 14 = π / 7 ≈ 0.449 seconds.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q77: Explain why simple pendulum oscillations are S.H.M ONLY for small angular amplitudes θ ≤ 10°.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Restoring force is F = -m g sinθ. Taylor expansion sinθ = θ - θ³/6 + ... For small angles (θ ≤ 10°), sinθ ≈ θ, making force linear F ∝ θ (S.H.M). For large angles, non-linear terms make period amplitude-dependent.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q78: Calculate speed of sound in air at 27°C and 1 atm pressure (γ = 1.4, M = 29 g/mol, R = 8.314 J/mol K).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T = 300 K, M = 0.029 kg/mol. v = √(γ R T / M) = √(1.4 × 8.314 × 300 / 0.029) = √(3491.88 / 0.029) = √(120409.65) ≈ 347.0 m/s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q79: A sonometer wire 80 cm long vibrates in 2 loops under tension 64 N. If linear density is 0.01 kg/m, find frequency.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> L = 0.80 m, 2 loops ⇒ 2nd harmonic (n=2). v = √(T / μ) = √(64 / 0.01) = √6400 = 80 m/s. Frequency f₂ = 2 × (v / 2L) = v / L = 80 / 0.80 = 100 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q80: Find the ratio of fundamental frequencies of an open organ pipe and a closed organ pipe of equal length L.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> f_open = v / (2L), f_closed = v / (4L). Ratio f_open / f_closed = (v/2L) / (v/4L) = 4/2 = 2 : 1.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q81: Why are acoustics of concert halls designed with curved back walls and sound-absorbing carpets?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Curved walls focus sound uniformly towards audience, while sound-absorbing carpets prevent excessive reverberation and echo overlap.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q82: Explain how beat frequency is used to detect dangerous inflammable gas leaks in underground mines.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Air from mine is pumped into one organ pipe and pure air into an identical pipe. If mine air contains gas, sound speed changes, producing audible beats that trigger alarms.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q83: A progressive wave on a string has amplitude 2 cm, frequency 50 Hz, and velocity 20 m/s. Write its wave equation.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> A = 0.02 m. ω = 2π ν = 100π rad/s. Wavelength λ = v / ν = 20 / 50 = 0.4 m. Wavenumber k = 2π / 0.4 = 5π rad/m. Equation: y(x,t) = 0.02 sin(5π x - 100π t) meters.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q84: What is end correction e in an organ pipe? Write corrected formulas for open and closed pipes of diameter D.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> End correction accounts for antinode forming slightly outside open end: e ≈ 0.3 D per open end.\n1. Open pipe (2 open ends): f = v / [2 (L + 2e)].\n2. Closed pipe (1 open end): f = v / [4 (L + e)].</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #00E5FF; font-size: 15.5px;\">Q85: Differentiate between Free, Damped, and Forced Oscillations with examples.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Free: Constant amplitude, natural frequency ω₀ (no friction).\n2. Damped: Amplitude decays exponentially due to viscous drag/friction (e.g. pendulum in water).\n3. Forced: Driven by external periodic force at driver frequency ω (e.g. swing pushed periodically).</p>\n    </div><h2 style=\"color: #00E5FF; border-bottom: 2px solid #00E5FF; padding-bottom: 6px; margin-top: 30px;\">SECTION 4: LONG ANSWER QUESTIONS (LAs 86 - 100)</h2>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q86: Define Simple Harmonic Motion. Derive differential equation d²x/dt² + ω² x = 0. Derive expressions for displacement x(t), velocity v(t), and acceleration a(t). Draw displacement, velocity, and acceleration graphs versus time.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Definition F = -k x.\n2. Derivation: m d²x/dt² + k x = 0 ⇒ d²x/dt² + ω² x = 0 (where ω = √(k/m)).\n3. x(t) = A cos(ω t).\n4. v(t) = -ω A sin(ω t).\n5. a(t) = -ω² A cos(ω t) = -ω² x.\n6. Graphs show velocity leads displacement by π/2, acceleration leads displacement by π (180° out of phase).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q87: What is a Simple Pendulum? Derive expression for its time period T = 2π √(L/g). State 4 laws of simple pendulum and explain why period is independent of bob mass.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Setup & restoring torque τ = -m g L sinθ ≈ -m g L θ.\n2. Equation I d²θ/dt² = -m g L θ ⇒ d²θ/dt² + (g/L) θ = 0 ⇒ T = 2π √(L/g).\n3. Law of Length (T ∝ √L), Law of Gravity (T ∝ 1/√g), Law of Mass (T independent of m), Law of Isochronism (T independent of small amplitude θ).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q88: Derive expressions for Kinetic Energy E_k and Potential Energy U of a simple harmonic oscillator. Plot E_k, U, and Total Energy E against displacement x. Show that average kinetic energy over one full period equals average potential energy.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. E_k = ½ m ω² (A² - x²), U = ½ m ω² x², E = E_k + U = ½ m ω² A².\n2. Graph plot: Intersections at x = ± A / √2.\n3. Time average over T: <E_k> = ¼ m ω² A², <U> = ¼ m ω² A² ⇒ <E_k> = <U> = ½ E_total.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q89: Derive expression for standing waves formed in a stretched string fixed at both ends. Find fundamental frequency and higher harmonics. Draw first three mode shapes.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Superposition of y₁ = A sin(kx - ωt) and y₂ = -A sin(kx + ωt) gives y = -2A sin(kx) cos(ωt).\n2. Boundary conditions y(0)=0 and y(L)=0 ⇒ sin(kL) = 0 ⇒ kL = nπ ⇒ λ_n = 2L / n.\n3. Frequencies f_n = n v / 2L = (n / 2L) √(T / μ) (n = 1, 2, 3... All harmonics present).\n4. 1st mode: 2 nodes at ends, 1 antinode in middle. 2nd mode: 3 nodes, 2 antinodes. 3rd mode: 4 nodes, 3 antinodes.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q90: Derive expressions for normal modes of standing waves in: (i) An open organ pipe, (ii) A closed organ pipe. Compare their fundamental frequencies and harmonic series.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Open pipe: Antinodes at both ends ⇒ L = n λ / 2 ⇒ f_n = n (v / 2L) (n = 1, 2, 3... All harmonics).\n2. Closed pipe: Node at closed end, Antinode at open end ⇒ L = (2n-1) λ / 4 ⇒ f_n = (2n-1) (v / 4L) (n = 1, 2, 3... Odd harmonics only).\n3. Comparison: Fundamental f_open = 2 f_closed for same length L. Open pipe has richer musical quality.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q91: What are Beats? State the principle of superposition and derive expression for beat frequency f_b = |f₁ - f₂|. Describe an experimental method to determine unknown frequency of a tuning fork.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Definition & Superposition y = y₁ + y₂.\n2. Mathematical proof deriving amplitude modulation 2A cos[π(f₁-f₂)t] and intensity variation frequency f_b = |f₁ - f₂|.\n3. Experimental tuning fork method: Sound unknown fork with standard fork f_std, count beats f_b. Load unknown with wax or file prong to confirm whether f_unk = f_std + f_b or f_std - f_b.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q92: A 0.5 kg body attached to horizontal spring executes S.H.M with equation x(t) = 0.08 cos(10 t - π/4) in meters. Calculate: (i) Amplitude, (ii) Frequency & Period, (iii) Spring constant k, (iv) Max speed & acceleration, (v) Initial displacement & velocity at t=0.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Amplitude A = 0.08 m = 8 cm.\n2. ω = 10 rad/s ⇒ ν = 10 / 2π = 1.59 Hz, T = 0.628 s.\n3. k = m ω² = 0.5 × 100 = 50 N/m.\n4. v_max = ω A = 10 × 0.08 = 0.8 m/s, a_max = ω² A = 100 × 0.08 = 8.0 m/s².\n5. t=0: x(0) = 0.08 cos(-π/4) = 0.08 / √2 = 0.0566 m. v(0) = -10 × 0.08 sin(-π/4) = +0.8 / √2 = +0.566 m/s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q93: A progressive transverse wave is represented by y = 0.04 sin(100 π t - 0.2 π x) where x,y in meters, t in seconds. Find: (i) Wave speed, (ii) Particle max speed, (iii) Phase difference between points 2.5 m apart, (iv) Transverse velocity at x=1 m, t=0.01 s.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. ω = 100π, k = 0.2π ⇒ Wave speed v = ω / k = 100π / 0.2π = 500 m/s.\n2. Particle v_max = ω A = 100π × 0.04 = 4π ≈ 12.57 m/s.\n3. Phase diff Δφ = k Δx = 0.2π × 2.5 = 0.5π = 90°.\n4. Transverse v_p = dy/dt = 0.04 × 100π cos(100π(0.01) - 0.2π(1)) = 4π cos(π - 0.2π) = 4π cos(0.8π) = 4π (-0.809) = -10.17 m/s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q94: A 2.0 m long sonometer wire under tension 100 N vibrates in 4 loops. If fundamental frequency is 25 Hz, find: (i) Wave speed in wire, (ii) Mass per unit length μ, (iii) Total mass of wire, (iv) Frequency of 4th harmonic.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Fundamental f₁ = 25 Hz ⇒ v / 2L = 25 ⇒ v = 25 × 2 × 2.0 = 100 m/s.\n2. v = √(T / μ) ⇒ μ = T / v² = 100 / (100)² = 100 / 10000 = 0.01 kg/m.\n3. Total mass m = μ L = 0.01 × 2.0 = 0.02 kg = 20 g.\n4. 4th harmonic f₄ = 4 f₁ = 4 × 25 = 100 Hz.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q95: Discuss Laplace's correction to Newton's formula for speed of sound in gases. Calculate speed of sound in Air at STP (P = 1.013 × 10⁵ Pa, ρ = 1.29 kg/m³, γ = 1.4) and at 50°C.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Newton Isothermal B=P vs Laplace Adiabatic B=γP.\n2. STP speed v_0 = √(γ P / ρ) = √(1.4 × 101300 / 1.29) = √(141820 / 1.29) = √109938 = 331.5 m/s.\n3. Speed at 50°C (323 K): v_T = v_0 √(T / 273) = 331.5 √(323 / 273) = 331.5 × 1.0877 = 360.6 m/s.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q96: Two organ pipes, one open of length 50 cm and one closed of length 24 cm, are sounded in their fundamental modes. Find beat frequency produced (v_sound = 340 m/s).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Open pipe f_open = v / (2 L_open) = 340 / (2 × 0.50) = 340 Hz.\n2. Closed pipe f_closed = v / (4 L_closed) = 340 / (4 × 0.24) = 340 / 0.96 = 354.17 Hz.\n3. Beat frequency f_b = |f_closed - f_open| = 354.17 - 340 = 14.17 Beats/second.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q97: State and prove the principle of superposition for two harmonic waves y₁ = A₁ sin(kx - ωt) and y₂ = A₂ sin(kx - ωt + φ). Derive expression for resultant amplitude A_net and phase. Find conditions for constructive and destructive interference.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Superposition y = y₁ + y₂.\n2. Resultant amplitude A_net = √(A₁² + A₂² + 2 A₁ A₂ cos φ).\n3. Constructive Interference: cos φ = +1 ⇒ φ = 2nπ ⇒ A_max = A₁ + A₂.\n4. Destructive Interference: cos φ = -1 ⇒ φ = (2n+1)π ⇒ A_min = |A₁ - A₂|.</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q98: A U-tube contains mercury up to height h. Show that liquid column executes S.H.M when pushed down on one side and released. Derive time period T = 2π √(L / 2g) where L is total column length.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. If liquid is depressed by x in one limb, height diff between limbs becomes 2x.\n2. Restoring force F = - (Area A) × (2x ρ g) = - (2 A ρ g) x.\n3. Total liquid mass m = A L ρ.\n4. Acceleration a = F / m = - (2 A ρ g x) / (A L ρ) = - (2g / L) x.\n5. Since a ∝ -x, motion is S.H.M with ω² = 2g / L ⇒ T = 2π √(L / 2g).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q99: A cylindrical body of mass m, area A, and density ρ_b floats vertically in a liquid of density ρ_l. Show that if pushed down slightly and released, it executes S.H.M. Derive expression for time period T.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Equilibrium buoyancy balances weight.\n2. When pushed down by x, additional buoyant force F = - A x ρ_l g.\n3. Acceleration a = F / m = - (A ρ_l g / m) x.\n4. Motion is S.H.M with ω² = A ρ_l g / m ⇒ T = 2π √(m / (A ρ_l g)).</p>\n    </div>\n    <div style=\"background: rgba(0, 229, 255, 0.04); border-left: 4px solid #00E5FF; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #00E5FF; font-size: 16px;\">Q100: Explain the phenomenon of Resonance in forced oscillations. Draw amplitude vs driving frequency graph for light, medium, and heavy damping. State two useful and two destructive effects of resonance.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Forced oscillation amplitude A = F₀ / √[m² (ω² - ω₀²)² + b² ω²].\n2. Resonance occurs when driving frequency ω = natural frequency ω₀, producing sharp maximum amplitude.\n3. Sharpness of resonance decreases as damping coefficient b increases.\n4. Useful: Tuning radio stations, musical instruments.\n5. Destructive: Soldiers marching across suspension bridges, earthquake structural collapse.</p>\n    </div></div>";
